def _components(board, color):
    unseen = {(x, y) for y in range(64) for x in range(64)
              if board[y][x] == color}
    ans = []
    while unseen:
        seed = unseen.pop()
        stack = [seed]
        comp = {seed}
        while stack:
            x, y = stack.pop()
            for q in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                if q in unseen:
                    unseen.remove(q)
                    comp.add(q)
                    stack.append(q)
        ans.append(comp)
